/* NEBSOFT Mobilya & Özel İmalat — talep, ölçü, teklif, kapora, üretim aşamaları, montaj takvimi, eksik listesi ve teslim.
   Temel kural: onaylanan teklif kilitlenir, her değişiklik yeni sürüm olarak müşteriye gider. Ölçü ve kapora kaydı imzalı kalır. */
(function () {
  'use strict';
  const { esc, $, $$, on, icon, money, toast, confirm, formModal, table, chart, badge, kpi, pageHead, sum, addDays, iso, today, modal } = NS;
  const O = window.MOB;
  const db = new NS.DB('mobilya', O.seed);
  const S = () => db.settings({});
  // Dizinler: binlerce kayıtta satır başına liste taranmasın. Çizim boyunca geçerli, kayıtta ve sonraki turda sıfırlanır
  const resets = []; const tick = (fn) => { let v = null; resets.push(() => { v = null; }); return () => { if (!v) { v = fn(); setTimeout(() => { v = null; }, 0); } return v; }; };
  const dbSave = db.save; db.save = function () { resets.forEach((f) => f()); return dbSave.apply(this, arguments); };
  const byId = (col) => tick(() => new Map(db.all(col).map((x) => [x.id, x])));
  const cusIx = byId('customers'); const payIx = tick(() => { const m = new Map(); db.all('payments').forEach((p) => m.set(p.job, O.r2((m.get(p.job) || 0) + (p.kind === 'iade' ? -1 : 1) * (Number(p.amount) || 0)))); return m; }); const jobsBy = tick(() => { const m = new Map(); db.all('jobs').forEach((j) => { if (!m.has(j.customer)) m.set(j.customer, []); m.get(j.customer).push(j); }); return m; });
  const cus = (id) => cusIx().get(id) || { name: '-', phone: '' };
  const team = (id) => db.get('teams', id) || { name: '-' };
  const stB = (s) => badge(O.ST[s][0], O.ST[s][1]);
  const vat = () => (S().vatRate != null ? Number(S().vatRate) : 20);
  const T = (j) => O.totals(j, vat());
  const pays = () => db.all('payments');
  const paid = (j) => payIx().get(j.id) || 0;
  const left = (j) => O.r2(T(j).total - paid(j));
  const role = () => (NS.currentUser || {}).role;
  const canMoney = () => ['admin', 'ofis'].includes(role()) || !role(); // usta ve montaj ekibi fiyat görmez
  const myTeam = () => (role() === 'montaj' ? NS.currentUser.team : null);
  const baseUrl = () => location.href.replace(/index\.html.*$/, '').replace(/[?#].*$/, '');
  const linkOf = (j) => baseUrl() + 'takip.html?k=' + j.key;
  const setSt = (j, st, note) => { j.status = st; (j.history = j.history || []).push({ at: new Date().toISOString(), st, note: note || O.ST[st][0], user: (NS.currentUser || {}).name }); };
  const nextNo = () => 'MB' + (Math.max(2600, ...db.all('jobs').map((x) => Number(String(x.no).replace(/\D/g, '')) || 0)) + 1);
  // SMS sonucu beklenir: gönderilmeyen mesaj "gönderildi" görünmez, simülasyon TEST yazar, olmazsa WhatsApp önerilir
  const waLink = (phone, text) => `https://wa.me/90${String(phone || '').replace(/\D/g, '').slice(-10)}?text=${encodeURIComponent(text)}`;
  async function smsSend(to, name, text) {
    const r = db.insert('sms', { to, name, text, status: 'gönderiliyor' }, true);
    const res = NS.integ ? await NS.integ.sms(to, text, { silent: true }) : { ok: false, error: 'SMS bağlantısı yok' };
    r.status = res.simulated ? 'TEST — gönderilmedi' : res.ok ? 'gönderildi' : 'gönderilmedi: ' + String(res.error || '').slice(0, 60); db.save();
    return { sent: !!res.ok && !res.simulated, test: !!res.simulated, error: res.simulated ? 'TEST modu — gerçek gönderim yapılmadı' : res.error || 'SMS gönderilemedi' };
  }
  async function tell(j, text, what) {
    const c = cus(j.customer); const r = await smsSend(c.phone, c.name, text);
    if (r.sent) { toast(`${what}: SMS gönderildi`, 'ok'); return r; }
    if (await confirm(`${what} SMS ile gönderilemedi (${r.error}). WhatsApp ile göndermek ister misiniz?`, { title: 'Müşteriye bildirim', ok: 'WhatsApp ile gönder', danger: false })) window.open(waLink(c.phone, text), '_blank', 'noopener');
    return r;
  }

  // ---------- Belgeler (işletmenin şablonuyla yazdırılır) ----------
  const measureLines = (j) => (j.measures || []).map((m) => `${m.place}: ${m.w || '-'} × ${m.h || '-'} × ${m.d || '-'} cm${m.qty > 1 ? ` · ${m.qty} adet` : ''}${m.note ? ' · ' + m.note : ''}`).join('\n');
  function quoteDoc(j, kind) {
    const c = cus(j.customer), t = T(j); const sz = kind === 'sozlesme';
    return { title: sz ? 'Sipariş sözleşmesi' : `Teklif${j.quoteV > 1 ? ' — sürüm ' + j.quoteV : ''}`, no: j.no, date: sz && j.approval ? j.approval.at : new Date().toISOString(),
      info: [['İş', j.title], ['Mekân', j.room || ''], ['Termin', j.deadline ? NS.date(j.deadline) : ''], ['Teklif geçerliliği', S().quoteDays ? S().quoteDays + ' gün' : '']],
      party: { title: 'Müşteri', name: c.name, lines: [c.phone, c.address, c.taxNo ? 'VKN/TCKN: ' + c.taxNo : ''] },
      lines: (j.items || []).map((i) => ({ name: i.name, note: O.KT[i.type] ? O.KT[i.type][0] : '', qty: i.qty, unit: i.unit, price: i.price, total: O.lineNet(i) })),
      totals: [['Ara toplam', t.brut], ...(t.disc ? [['İndirim', -t.disc]] : []), [`KDV %${t.rate}`, t.kdv], ['GENEL TOPLAM', t.total, true], ...(sz ? [['Alınan ödeme', paid(j)], ['Kalan', left(j)]] : [])],
      note: [measureLines(j) ? 'Ölçüler:\n' + measureLines(j) : '', sz && j.channel === 'mesafeli' ? O.DISTANCE_NOTE : '', sz ? S().contractText || '' : S().quoteNote || ''].filter(Boolean).join('\n\n'),
      signatures: [{ label: 'İşletme', name: S().bizName }, { label: sz ? 'Müşteri (sözleşmeyi okudum, onaylıyorum)' : 'Müşteri onayı', ...(j.contractSign || j.approval || {}) }] };
  }
  // Üretim föyü atölyeye gider: fiyat içermez
  function workDoc(j) {
    const c = cus(j.customer);
    return { title: 'Üretim föyü', no: j.no, date: new Date().toISOString(), info: [['İş', j.title], ['Müşteri', c.name], ['Termin', j.deadline ? NS.date(j.deadline) : ''], ['Montaj', j.installAt ? NS.date(j.installAt) : ''], ['Ölçü sürümü', j.measureRev || 1], ['Teklif sürümü', j.quoteV || 1]],
      lines: (j.items || []).filter((i) => i.type !== 'hizmet').map((i) => ({ name: i.name, note: O.KT[i.type] ? O.KT[i.type][0] : '', qty: i.qty, unit: i.unit })), note: 'Ölçüler:\n' + (measureLines(j) || '-') + (j.workNote ? '\n\nAtölye notu: ' + j.workNote : ''), signatures: [{ label: 'Üretimi yapan' }, { label: 'Kontrol eden' }] };
  }
  function deliveryDoc(j) {
    const c = cus(j.customer); const P = O.openPunch(j);
    return { title: 'Montaj ve teslim tutanağı', no: j.no, date: j.deliveredAt || new Date().toISOString(), info: [['İş', j.title], ['Montaj ekibi', team(j.team).name], ['Montaj tarihi', j.installAt ? NS.date(j.installAt) : ''], ...(j.pkgCount ? [['Koli / parça sayısı', j.pkgCount]] : []), ...(j.warrantyUntil ? [['Garanti bitişi', NS.date(j.warrantyUntil)]] : [])],
      party: { title: 'Müşteri', name: c.name, lines: [c.phone, j.address] }, lines: (j.items || []).filter((i) => i.type !== 'hizmet').map((i) => ({ name: i.name, qty: i.qty, unit: i.unit })),
      note: P.length ? 'Açık eksikler:\n' + P.map((p) => '• ' + p.text).join('\n') : 'Montajı tamamlanan ürünler kontrol edilerek teslim alınmıştır.', signatures: [{ label: 'Montaj ekibi', name: team(j.team).lead || '' }, { label: 'Teslim alan müşteri', ...(j.signOut || {}) }] };
  }
  const warrantyDoc = (j) => { const c = cus(j.customer); return { title: 'Garanti belgesi', no: j.no, date: j.deliveredAt || new Date().toISOString(), party: { title: 'Müşteri', name: c.name, lines: [c.phone, j.address] }, info: [['Ürün', j.title], ['Teslim tarihi', j.deliveredAt ? NS.date(j.deliveredAt) : ''], ['Garanti bitişi', j.warrantyUntil ? NS.date(j.warrantyUntil) : '']], lines: (j.items || []).filter((i) => i.type !== 'hizmet').map((i) => ({ name: i.name, qty: i.qty, unit: i.unit })), note: S().warrantyText || 'Garanti süresi malın teslim tarihinden başlar.', signatures: [{ label: 'İmalatçı / satıcı', name: S().bizName }] }; };
  const receiptDoc = (p) => { const j = db.get('jobs', p.job) || {}; const c = cus(p.customer); return { title: `${O.PAY[p.kind] || 'Ödeme'} makbuzu`, no: p.no || j.no, date: p.at, party: { title: 'Müşteri', name: c.name, lines: [c.phone] }, info: [['İş', `${j.no || ''} ${j.title || ''}`], ['Ödeme türü', p.method || '']], lines: [{ name: O.PAY[p.kind] || 'Ödeme', qty: 1, unit: '', price: p.amount, total: p.amount }], totals: [['Tutar', p.amount, true]], note: 'Bu belge tahsilat kaydıdır, mali belge yerine geçmez.', signatures: [{ label: 'Tahsil eden', name: S().bizName }, { label: 'Ödeyen' }] }; };
  if (NS.docs) {
    const sample = (fn) => () => { const j = db.all('jobs').find((x) => x.items.length); return j ? fn(j) : { title: 'Örnek' }; };
    NS.docs.define('mobilya', 'teklif', { label: 'Teklif', sample: sample((j) => quoteDoc(j, 'teklif')) });
    NS.docs.define('mobilya', 'sozlesme', { label: 'Sipariş sözleşmesi', sample: sample((j) => quoteDoc(j, 'sozlesme')) });
    NS.docs.define('mobilya', 'foy', { label: 'Üretim föyü', sample: sample(workDoc) });
    NS.docs.define('mobilya', 'teslim', { label: 'Montaj ve teslim tutanağı', sample: sample(deliveryDoc) });
    NS.docs.define('mobilya', 'garanti', { label: 'Garanti belgesi', sample: sample(warrantyDoc) });
    NS.docs.define('mobilya', 'makbuz', { label: 'Tahsilat makbuzu', sample: () => { const p = pays()[0]; return p ? receiptDoc(p) : { title: 'Örnek' }; } });
  }

  // Fotoğraf: en fazla 1000 px, JPEG. İş kartında en çok 6 tane tutulur, buluta küçük boyutla gider
  const shrink = (file) => new Promise((res) => { const r = new FileReader(); r.onload = () => { const im = new Image(); im.onload = () => { const k = Math.min(1, 1000 / Math.max(im.width, im.height)); const c = document.createElement('canvas'); c.width = im.width * k; c.height = im.height * k; c.getContext('2d').drawImage(im, 0, 0, c.width, c.height); res(c.toDataURL('image/jpeg', 0.72)); }; im.onerror = () => res(null); im.src = r.result; }; r.readAsDataURL(file); });
  // ---------- Ortak formlar ----------
  async function newJob(app, preset = {}) {
    const C = db.all('customers').sort((a, b) => a.name.localeCompare(b.name, 'tr'));
    const v = await formModal({ title: 'Yeni talep', size: 'wide', fields: [{ name: 'customer', label: 'Kayıtlı müşteri', type: 'select', empty: 'Yeni müşteri', options: C.map((c) => ({ value: c.id, label: `${c.name} · ${c.phone}` })) }, { name: 'cname', label: 'Yeni müşteri adı' }, { name: 'cphone', label: 'Yeni müşteri telefonu', type: 'tel' }, { name: 'title', label: 'İstenen iş', required: true, placeholder: 'Mutfak dolabı, gardırop…' }, { name: 'room', label: 'Mekân' }, { name: 'source', label: 'Nereden geldi', type: 'select', options: ['Tavsiye', 'Instagram', 'Google', 'Web sitesi', 'Mağaza', 'Diğer'] }, { name: 'address', label: 'Adres', full: true }, { name: 'deadline', label: 'Söz verilen termin', type: 'date' }, { name: 'channel', label: 'Satış şekli', type: 'select', options: [{ value: 'yuzyuze', label: 'Yüz yüze' }, { value: 'mesafeli', label: 'Mesafeli (telefon, internet)' }] }, { name: 'note', label: 'Not', type: 'textarea', full: true }], values: { deadline: iso(addDays(new Date(), Number(S().deadlineDays) || 30)), ...preset } });
    if (!v) return null;
    let c = v.customer ? db.get('customers', v.customer) : null;
    if (!c) { if (!String(v.cname || '').trim() || String(v.cphone || '').replace(/\D/g, '').length < 10) { toast('Müşteri seçin veya ad ve telefon yazın', 'err'); return null; } c = db.insert('customers', { name: v.cname.trim(), phone: v.cphone, address: v.address, source: v.source }, true); }
    const j = db.insert('jobs', { key: O.newKey(), no: nextNo(), customer: c.id, title: v.title, room: v.room, source: v.source, address: v.address || c.address || '', deadline: v.deadline, channel: v.channel || 'yuzyuze', note: v.note, status: 'talep', at: new Date().toISOString(), items: [], measures: [], stages: {}, punch: [], disc: 0, quoteV: 1, quotes: [], history: [{ at: new Date().toISOString(), st: 'talep', note: 'Talep alındı', user: (NS.currentUser || {}).name }] }, true);
    db.save(); toast(`${j.no} açıldı`, 'ok'); app.go('is', j.id); return j;
  }
  async function takePayment(j, kind, draw) {
    const t = T(j); const dep = kind === 'kapora'; const rest = Math.max(0, left(j));
    const v = await formModal({ title: `${O.PAY[kind]} — ${j.no}`, fields: [{ name: 'amount', label: 'Tutar (₺)', type: 'number', step: '0.01', required: true }, { name: 'method', label: 'Yöntem', type: 'select', options: ['Nakit', 'Kredi kartı', 'Havale'] }, { name: 'note', label: 'Not', full: true }, { name: 'print', label: 'Makbuz yazdır', type: 'checkbox' }], values: { amount: dep ? O.r2(t.total * (Number(S().minDeposit) || 0) / 100) : rest, method: 'Havale', print: dep } });
    if (!v) return null; const a = Number(v.amount); if (!(a > 0)) { toast('Tutar sıfırdan büyük olmalı', 'err'); return null; }
    if (kind !== 'iade' && a > rest + 0.01 && !(await confirm(`Tutar kalan ${money(rest)} borçtan büyük. Yine de kaydedilsin mi?`, { danger: false }))) return null;
    const p = db.insert('payments', { job: j.id, customer: j.customer, amount: a, kind, method: v.method, note: v.note, at: new Date().toISOString(), user: (NS.currentUser || {}).name }, true); db.save();
    if (v.print) NS.docs.print('makbuz', receiptDoc(p)); toast(`${O.PAY[kind]} kaydedildi`, 'ok'); if (draw) draw(); return p;
  }
  // Stok: ilk üretimde tamamı, değişiklik teklifinden dönüşte yalnız fark düşer
  const useMaterials = (j) => { const short = []; Object.entries(O.usageDiff(j)).forEach(([id, q]) => { const m = db.get('materials', id); if (!m) return; if (q > 0 && (m.stock || 0) < q) short.push(`${m.name} (stok ${m.stock}, gerekli ${q})`); m.stock = Math.max(0, O.r2((m.stock || 0) - q)); }); j.used = O.usage(j); j.materialsUsed = true; return short; };

  // ---------- İşler (pano) ----------
  function jobsPage(el, p, app) {
    let q = ''; const mine = myTeam(); const money_ = canMoney();
    el.innerHTML = pageHead('İşler', mine ? 'Ekibinize atanan montajlar' : 'Talepten teslime tüm işler. Karta tıklayın.', mine ? '' : `<button class="btn primary" id="ad">${icon('plus')} Yeni talep</button>`) + `<div class="card pad mb">${NS.searchBox('q', 'Müşteri, iş no, iş adı…')}</div><div class="grid" style="grid-template-columns:repeat(6,minmax(190px,1fr));overflow-x:auto;gap:12px" id="kb"></div><div class="card mt"><div class="card-h"><h3>Son biten işler</h3></div><div id="done"></div></div>`;
    const card = (j) => { const lt = O.late(j, today()); return `<div class="card pad mb" data-j="${j.id}" style="cursor:pointer${lt ? ';border-color:var(--err)' : ''}"><div class="row"><b class="grow">${esc(cus(j.customer).name)}</b><span class="small faint mono">${esc(j.no)}</span></div><div class="small muted">${esc(j.title)}</div>${j.status === 'uretim' ? `<div class="small mt">${O.stageDone(j)}/${O.STAGES.length} aşama</div>` : ''}<div class="row small mt"><span class="grow faint">${j.status === 'montaj' && j.installAt ? 'Montaj ' + NS.date(j.installAt) : j.deadline ? 'Termin ' + NS.date(j.deadline) : ''}</span>${lt ? badge('Gecikti', 'err') : ''}${money_ && j.items.length ? `<b>${money(T(j).total)}</b>` : ''}</div></div>`; };
    const draw = () => {
      const all = db.all('jobs', (j) => (!mine || j.team === mine) && NS.match(q, j.no, j.title, cus(j.customer).name, cus(j.customer).phone));
      $('#kb', el).innerHTML = O.FLOW.slice(0, 6).map((s) => { const L = all.filter((j) => j.status === s); return `<div><div class="row mb"><b class="grow">${esc(O.ST[s][0])}</b>${badge(L.length, O.ST[s][1])}</div>${L.map(card).join('') || '<div class="small faint">—</div>'}</div>`; }).join('');
      $('#done', el).innerHTML = table({ rows: all.filter(O.closed).sort((a, b) => (b.deliveredAt || b.at).localeCompare(a.deliveredAt || a.at)).slice(0, 20), empty: 'Henüz biten iş yok', emptyIcon: 'check', columns: [{ label: 'İş', render: (j) => `<b>${esc(j.title)}</b> <span class="small faint">${esc(j.no)}</span>` }, { label: 'Müşteri', render: (j) => esc(cus(j.customer).name) }, { label: 'Durum', render: (j) => stB(j.status) }, ...(money_ ? [{ label: 'Tutar', cls: 'right', render: (j) => money(T(j).total) }, { label: 'Kalan', cls: 'right', render: (j) => (j.status === 'iptal' ? '-' : left(j) > 0.01 ? `<b style="color:var(--err)">${money(left(j))}</b>` : badge('Ödendi', 'ok')) }] : [])], actions: [{ icon: 'eye', act: 'v', title: 'Aç' }] });
    };
    $('#q', el).oninput = (e) => { q = e.target.value; draw(); };
    on(el, 'click', '[data-j]', (e, b) => app.go('is', b.dataset.j)); on(el, 'click', '[data-act=v]', (e, b) => app.go('is', b.dataset.id));
    const ad = $('#ad', el); if (ad) ad.onclick = () => newJob(app);
    draw();
  }

  // ---------- İş kartı ----------
  function jobPage(el, id, app) {
    const j = db.get('jobs', id);
    if (!j) { el.innerHTML = `<div class="card pad empty">${icon('alert')}<div>İş bulunamadı</div><a class="btn mt" href="#/isler">İşlere dön</a></div>`; return; }
    if (myTeam() && j.team !== myTeam()) { el.innerHTML = `<div class="card pad empty">${icon('lock')}<div>Bu iş ekibinize atanmadı</div></div>`; return; }
    const off = canMoney(); let tab = j.status === 'talep' || j.status === 'olcu' ? 'olcu' : ['uretim'].includes(j.status) ? 'uretim' : ['montaj', 'teslim'].includes(j.status) ? 'teslim' : 'teklif'; if (!off && tab === 'teklif') tab = 'olcu';
    let saveT = null; const later = () => { clearTimeout(saveT); saveT = setTimeout(() => db.save(), 400); };
    const lockItems = () => O.locked(j) || !off;
    const FLOWBTN = () => (!off ? (j.status === 'uretim' && O.stageDone(j) === O.STAGES.length && role() === 'usta' ? [] : []) : ({
      talep: [['olcu', 'Ölçü randevusu ver', 'calendar', 'primary'], ['iptal', 'İptal et', 'x', 'ghost']],
      olcu: [['teklif', 'Ölçü bitti, teklife geç', 'file', 'primary'], ['iptal', 'İptal et', 'x', 'ghost']],
      teklif: [['gonder', 'Teklifi gönder', 'send', 'primary'], ['onay', 'Müşteri onayladı', 'check', ''], ['iptal', 'İptal et', 'x', 'ghost']],
      onay: [['kapora', 'Kapora al ve üretime gönder', 'wallet', 'primary'], ['revize', 'Değişiklik teklifi aç', 'edit', ''], ['iptal', 'İptal et', 'x', 'ghost']],
      uretim: [...(O.stageDone(j) === O.STAGES.length ? [['montaj', 'Montaja planla', 'calendar', 'primary']] : []), ['revize', 'Değişiklik teklifi aç', 'edit', ''], ['iptal', 'İptal et', 'x', 'ghost']],
      montaj: [['teslim', 'Teslim et ve tahsil et', 'check', 'primary'], ['montaj', 'Montajı yeniden planla', 'calendar', '']],
    }[j.status] || []));
    const lineRow = (i, n) => { const L = lockItems(); return `<tr data-row="${i.id}"><td class="faint">${n + 1}</td><td>${L ? badge(O.KT[i.type][0], O.KT[i.type][1]) : `<select class="input os-in" data-k="type">${Object.entries(O.KT).map(([k, [l]]) => `<option value="${k}" ${k === i.type ? 'selected' : ''}>${l}</option>`).join('')}</select>`}</td><td style="min-width:200px">${L ? esc(i.name) : `<input class="input os-in" data-k="name" value="${esc(i.name)}">`}</td><td class="right">${L ? `${i.qty} ${esc(i.unit || '')}` : `<input class="input os-in os-n" data-k="qty" type="number" step="0.1" min="0" value="${i.qty}">`}</td>${off ? `<td class="right">${L ? money(i.price) : `<input class="input os-in os-n" data-k="price" type="number" step="0.01" min="0" value="${i.price}">`}</td><td class="right"><b data-tot>${money(O.lineNet(i))}</b></td>${role() === 'admin' ? `<td class="right small faint">${money((Number(i.cost) || 0) * (Number(i.qty) || 0))}</td>` : ''}` : ''}<td>${L ? '' : `<button class="btn sm icon ghost" data-rm="${i.id}" title="Kalemi sil">${icon('trash')}</button>`}</td></tr>`; };
    const totalsHtml = () => { const t = T(j); const c = O.costOf(j); return `${[['Ara toplam', t.brut], ['KDV %' + t.rate, t.kdv]].map(([l, x]) => `<div class="list-item small"><span class="grow muted">${l}</span>${money(x)}</div>`).join('')}${off && !lockItems() ? `<div class="list-item small"><span class="grow muted">İndirim (₺)</span><input class="input os-n" id="disc" type="number" step="0.01" min="0" value="${j.disc || ''}" style="width:110px"></div>` : t.disc ? `<div class="list-item small"><span class="grow muted">İndirim</span>${money(-t.disc)}</div>` : ''}<div class="list-item"><b class="grow">Genel toplam</b><b style="font-size:22px">${money(t.total)}</b></div>${role() === 'admin' && c ? `<div class="list-item small"><span class="grow muted">Maliyet · brüt kâr</span>${money(c)} · <b>${money(t.net - c)}</b></div>` : ''}`; };
    const tabHtml = () => {
      if (tab === 'olcu') return `<div class="card"><div class="card-h"><h3>${icon('edit')} Ölçüler${j.measureRev > 1 ? ` · sürüm ${j.measureRev}` : ''}</h3>${O.locked(j) ? '' : `<button class="btn sm" data-addm>${icon('plus')} Ölçü ekle</button>`}</div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Yer</th><th class="right">En</th><th class="right">Boy</th><th class="right">Derinlik</th><th class="right">Adet</th><th>Not</th><th></th></tr></thead><tbody>${(j.measures || []).map((m) => `<tr data-m="${m.id}">${O.locked(j) ? `<td><b>${esc(m.place)}</b></td><td class="right">${m.w || '-'}</td><td class="right">${m.h || '-'}</td><td class="right">${m.d || '-'}</td><td class="right">${m.qty || 1}</td><td class="small">${esc(m.note || '')}</td><td></td>` : `<td><input class="input os-in" data-mk="place" value="${esc(m.place)}"></td>${['w', 'h', 'd', 'qty'].map((k) => `<td class="right"><input class="input os-in os-n" type="number" step="0.1" data-mk="${k}" value="${m[k] == null ? '' : m[k]}"></td>`).join('')}<td><input class="input os-in" data-mk="note" value="${esc(m.note || '')}"></td><td><button class="btn sm icon ghost" data-rmm="${m.id}" title="Sil">${icon('trash')}</button></td>`}</tr>`).join('') || '<tr><td colspan="7" class="center muted" style="padding:24px">Henüz ölçü yok. Yerinde ölçüyü burada kaydedin; ölçüler santimetredir.</td></tr>'}</tbody></table></div></div>
        <div class="card pad mt"><h3 class="mb">Fotoğraflar</h3><div class="os-photos">${(j.photos || []).map((ph, i) => `<div class="os-ph"><a href="${ph}" target="_blank" rel="noopener"><img src="${ph}" alt="İş fotoğrafı ${i + 1}"></a><button class="btn sm icon" data-rph="${i}" title="Sil">${icon('x')}</button></div>`).join('')}${(j.photos || []).length < 6 ? `<label class="os-ph add">${icon('camera')}<span class="small">Fotoğraf</span><input type="file" accept="image/*" capture="environment" multiple hidden id="ph"></label>` : ''}</div></div><div class="card pad mt"><h3 class="mb">Ölçü onayı</h3>${j.measureSign ? `<div class="os-sig"><img src="${j.measureSign.img}" alt="Ölçü onay imzası"><div class="small muted">${esc(j.measureSign.name)} · ${NS.dt(j.measureSign.at)}</div></div>` : '<p class="small muted mb">Müşteri ölçüleri yerinde kontrol edip imzalar; sonradan çıkan ölçü tartışmasında bu kayıt kalır.</p>'}${O.locked(j) ? '' : `<button class="btn block mt" data-msign>${icon('edit')} ${j.measureSign ? 'Yeniden imzalat' : 'Müşteriye imzalat'}</button>`}</div>`;
      if (tab === 'teklif') return `<div class="card"><div class="card-h"><h3>${icon('list')} Teklif kalemleri · sürüm ${j.quoteV || 1}</h3>${lockItems() ? badge('Kilitli', 'info') : `<div class="row" style="gap:6px"><button class="btn sm" data-add>${icon('plus')} Kalem</button><button class="btn sm soft" data-cat>${icon('book')} Katalogdan</button><button class="btn sm soft" data-mat>${icon('box')} Malzemeden</button></div>`}</div><div class="tbl-wrap"><table class="tbl os-lines"><thead><tr><th>#</th><th>Tür</th><th>Açıklama</th><th class="right">Miktar</th><th class="right">Birim fiyat</th><th class="right">Tutar</th>${role() === 'admin' ? '<th class="right">Maliyet</th>' : ''}<th></th></tr></thead><tbody id="ln">${(j.items || []).map(lineRow).join('') || `<tr><td colspan="8" class="center muted" style="padding:24px">Henüz kalem yok. Katalogdan seçin veya kalem ekleyin.</td></tr>`}</tbody></table></div><div class="card-b" id="tt" style="max-width:380px;margin-left:auto">${totalsHtml()}</div></div>
        <div class="row mt"><button class="btn" data-pr="teklif">${icon('print')} Teklifi yazdır</button><button class="btn" data-pr="sozlesme">${icon('print')} Sözleşme yazdır</button><button class="btn" data-link>${icon('link')} Müşteri linkini kopyala</button></div>
        ${(j.quotes || []).length ? `<div class="card mt"><div class="card-h"><h3>Teklif sürümleri</h3></div>${table({ rows: j.quotes.map((x) => ({ ...x, id: 'q' + x.v })), columns: [{ label: 'Sürüm', render: (x) => x.v }, { label: 'Tarih', render: (x) => NS.dt(x.at) }, { label: 'Kalem', cls: 'right', render: (x) => x.items.length }, { label: 'Toplam', cls: 'right', render: (x) => money(x.total) }] })}</div>` : ''}${j.revNote ? `<div class="card pad mt" style="border-color:var(--warn)"><b>Müşterinin değişiklik isteği:</b> ${esc(j.revNote)}</div>` : ''}`;
      if (tab === 'uretim') return `<div class="card pad"><h3 class="mb">${icon('factory')} Üretim aşamaları</h3><div class="col" style="gap:8px">${O.STAGES.map(([k, l], i) => { const s = (j.stages || {})[k]; const can = j.status === 'uretim' && (off || role() === 'usta'); return `<label class="row" style="padding:10px 12px;border:1px solid var(--border);border-radius:10px;${s ? 'background:var(--ok-soft)' : ''}"><input type="checkbox" data-stage="${k}" ${s ? 'checked' : ''} ${can ? '' : 'disabled'} style="width:20px;height:20px"><b class="grow">${i + 1}. ${esc(l)}</b><span class="small faint">${s ? `${esc(s.by || '')} · ${NS.dt(s.at)}` : ''}</span></label>`; }).join('')}</div><div class="field mt"><label>Atölye notu</label><textarea class="input" rows="2" data-j="workNote" ${j.status === 'uretim' && (off || role() === 'usta') ? '' : 'readonly'}>${esc(j.workNote || '')}</textarea></div><div class="field mt"><label>Koli / parça sayısı (sevk öncesi sayım)</label><input class="input" type="number" min="0" data-j="pkgCount" value="${esc(j.pkgCount || '')}" ${j.status === 'uretim' && (off || role() === 'usta') ? '' : 'readonly'} style="max-width:160px"></div><button class="btn mt" data-pr="foy">${icon('print')} Üretim föyü</button></div>`;
      if (tab === 'odeme') { const P = pays().filter((p) => p.job === j.id).sort((a, b) => a.at.localeCompare(b.at)); return `<div class="grid g3 mb">${kpi('Toplam', money(T(j).total), 'file', 'info')}${kpi('Alınan', money(paid(j)), 'wallet', 'ok')}${kpi('Kalan', money(left(j)), 'cash', left(j) > 0.01 ? 'err' : 'ok')}</div><div class="card"><div class="card-h"><h3>Ödemeler</h3>${j.status === 'iptal' ? '' : `<div class="row" style="gap:6px"><button class="btn sm" data-pay="kapora">Kapora</button><button class="btn sm" data-pay="ara">Ara ödeme</button><button class="btn sm" data-pay="son">Son ödeme</button></div>`}<button class="btn sm ghost" data-pay="iade">İade</button></div>${table({ rows: P, empty: 'Henüz ödeme yok', emptyIcon: 'wallet', columns: [{ label: 'Tarih', render: (x) => NS.dt(x.at) }, { label: 'Tür', render: (x) => badge(O.PAY[x.kind] || x.kind, x.kind === 'iade' ? 'err' : 'ok') }, { label: 'Yöntem', render: (x) => esc(x.method || '') }, { label: 'Tutar', cls: 'right', render: (x) => money(x.amount) }], actions: [{ icon: 'print', act: 'rc', title: 'Makbuz' }] })}</div>`; }
      const P = j.punch || []; return `<div class="card"><div class="card-h"><h3>${icon('list')} Eksik listesi</h3><button class="btn sm" data-addp>${icon('plus')} Eksik ekle</button></div>${P.length ? P.map((x) => `<label class="list-item"><input type="checkbox" data-punch="${x.id}" ${x.done ? 'checked' : ''} style="width:20px;height:20px"><span class="grow" style="${x.done ? 'text-decoration:line-through;color:var(--text-3)' : ''}">${esc(x.text)}</span><span class="small faint">${x.done && x.at ? NS.dt(x.at) : ''}</span></label>`).join('') : '<div class="empty"><div>Eksik yok</div></div>'}</div><div class="card pad mt"><h3 class="mb">Teslim</h3><div class="kv small"><b>Montaj</b><span>${j.installAt ? NS.date(j.installAt) : 'Planlanmadı'} · ${esc(team(j.team).name)}</span><b>Teslim</b><span>${j.deliveredAt ? NS.dt(j.deliveredAt) : '-'}</span><b>Garanti bitişi</b><span>${j.warrantyUntil ? NS.date(j.warrantyUntil) : '-'}</span>${j.invoice ? `<b>Fatura</b><span>${esc(j.invoice)}</span>` : ''}</div>${j.signOut ? `<div class="os-sig mt"><img src="${j.signOut.img}" alt="Teslim imzası"><div class="small muted">${esc(j.signOut.name)} · ${NS.dt(j.signOut.at)}</div></div>` : ''}<div class="row mt"><button class="btn" data-pr="teslim">${icon('print')} Teslim tutanağı</button>${j.deliveredAt ? `<button class="btn" data-pr="garanti">${icon('print')} Garanti belgesi</button><button class="btn" data-claim>${icon('alert')} Ayıp ve servis kaydı aç</button>` : ''}</div></div>`;
    };
    function draw() {
      const c = cus(j.customer); const idx = O.FLOW.indexOf(j.status === 'iptal' ? 'talep' : j.status); const TABS = [['olcu', 'Ölçü'], ...(off ? [['teklif', 'Teklif']] : []), ['uretim', 'Üretim'], ...(off ? [['odeme', 'Ödeme']] : []), ['teslim', 'Montaj ve teslim']];
      el.innerHTML = `<div class="page-h"><div class="grow"><div class="row mb" style="gap:8px"><a class="btn sm ghost" href="#/isler">${icon('back')} İşler</a>${stB(j.status)}<span class="small faint mono">${esc(j.no)}</span>${O.late(j, today()) ? badge('Termin geçti', 'err') : ''}</div><h1>${esc(j.title)}</h1><p>${esc(c.name)} · ${esc(c.phone)}${j.address ? ' · ' + esc(j.address) : ''}${j.deadline ? ' · Termin ' + NS.date(j.deadline) : ''}</p></div><div class="row">${c.phone ? `<a class="btn" href="tel:${esc(String(c.phone).replace(/[^\d+]/g, ''))}">${icon('phone')}</a>` : ''}${FLOWBTN().map(([k, l, ic, cls]) => `<button class="btn ${cls}" data-flow="${k}">${icon(ic)} ${l}</button>`).join('')}</div></div>
        ${j.status === 'iptal' ? `<div class="card pad mb"><b>İptal nedeni:</b> ${esc(j.cancel || '-')}</div>` : `<div class="os-steps mb">${O.FLOW.map((s, i) => `<div class="os-step ${i < idx ? 'done' : i === idx ? 'cur' : ''}"><span>${i < idx ? icon('check') : i + 1}</span>${esc(O.ST[s][0])}</div>`).join('')}</div>`}
        <div class="tabs">${TABS.map(([k, l]) => `<button data-tb="${k}" class="${k === tab ? 'active' : ''}">${esc(l)}</button>`).join('')}</div><div id="tb">${tabHtml()}</div>
        <div class="card pad mt"><h3 class="mb">Geçmiş</h3><div class="col" style="gap:6px">${(j.history || []).slice().reverse().slice(0, 12).map((h) => `<div class="small"><b>${esc((O.ST[h.st] || [''])[0])}</b> — ${esc(h.note || '')} <span class="faint">${NS.dt(h.at)}${h.user ? ' · ' + esc(h.user) : ''}</span></div>`).join('')}</div></div>`;
    }
    const addLine = (it) => { (j.items = j.items || []).push({ id: NS.uid(), type: 'malzeme', qty: 1, unit: 'adet', price: 0, cost: 0, ...it }); db.save(); draw(); };
    el.addEventListener('input', (e) => {
      const tr = e.target.closest('[data-row]'); const k = e.target.dataset.k;
      if (tr && k) { const i = j.items.find((x) => x.id === tr.dataset.row); if (!i) return; i[k] = ['qty', 'price'].includes(k) ? Number(e.target.value) || 0 : e.target.value; const c = $('[data-tot]', tr); if (c) c.textContent = money(O.lineNet(i)); const t = $('#tt', el); if (t && e.target.id !== 'disc') t.innerHTML = totalsHtml(); later(); }
      const m = e.target.closest('[data-m]'); const mk = e.target.dataset.mk; if (m && mk) { const x = j.measures.find((y) => y.id === m.dataset.m); if (x) { x[mk] = ['place', 'note'].includes(mk) ? e.target.value : Number(e.target.value) || 0; later(); } }
      if (e.target.dataset.j) { j[e.target.dataset.j] = e.target.value; later(); }
    });
    el.addEventListener('change', async (e) => {
      if (e.target.id === 'ph') { j.photos = j.photos || []; for (const f of [...e.target.files].slice(0, 6 - j.photos.length)) { const d = await shrink(f); if (d) j.photos.push(d); } db.save(); draw(); return; }
      if (e.target.id === 'disc') { j.disc = Math.max(0, Number(e.target.value) || 0); db.save(); $('#tt', el).innerHTML = totalsHtml(); return; }
      const k = e.target.dataset.stage; if (k) { j.stages = j.stages || {}; if (e.target.checked) j.stages[k] = { at: new Date().toISOString(), by: (NS.currentUser || {}).name || '' }; else delete j.stages[k]; (j.history = j.history || []).push({ at: new Date().toISOString(), st: 'uretim', note: `${(O.STAGES.find((s) => s[0] === k) || [0, k])[1]} ${e.target.checked ? 'bitti' : 'geri alındı'}`, user: (NS.currentUser || {}).name }); db.save(); draw(); return; }
      const pu = e.target.dataset.punch; if (pu) { const x = j.punch.find((y) => y.id === pu); x.done = e.target.checked; x.at = x.done ? new Date().toISOString() : null; db.save(); draw(); }
    });
    el.addEventListener('click', async (e) => {
      const tb = e.target.closest('[data-tb]'); if (tb) { tab = tb.dataset.tb; draw(); return; }
      const b = e.target.closest('button'); if (!b) return;
      if (b.dataset.rm) { j.items = j.items.filter((i) => i.id !== b.dataset.rm); db.save(); draw(); return; }
      if (b.dataset.rph != null) { j.photos.splice(Number(b.dataset.rph), 1); db.save(); draw(); return; }
      if (b.dataset.rmm) { j.measures = j.measures.filter((m) => m.id !== b.dataset.rmm); db.save(); draw(); return; }
      if (b.hasAttribute('data-addm')) { (j.measures = j.measures || []).push({ id: NS.uid(), place: j.room || 'Duvar', w: null, h: null, d: null, qty: 1, note: '' }); db.save(); draw(); return; }
      if (b.hasAttribute('data-add')) return addLine({ name: 'Yeni kalem' });
      if (b.hasAttribute('data-cat')) { const L = db.all('catalog'); const v = await formModal({ title: 'Katalogdan ekle', fields: [{ name: 'c', label: 'Kalem', type: 'select', options: L.map((x) => ({ value: x.id, label: `${x.name} · ${money(x.price)}/${x.unit}` })), full: true }, { name: 'qty', label: 'Miktar', type: 'number', step: '0.1' }], values: { qty: 1 } }); if (!v) return; const x = db.get('catalog', v.c); return addLine({ type: x.type, name: x.name, qty: Number(v.qty) || 1, unit: x.unit, price: x.price, cost: x.cost || 0 }); }
      if (b.hasAttribute('data-mat')) { const L = db.all('materials'); const v = await formModal({ title: 'Malzemeden ekle', fields: [{ name: 'm', label: 'Malzeme', type: 'select', options: L.map((x) => ({ value: x.id, label: `${x.code} · ${x.name} · stok ${x.stock}` })), full: true }, { name: 'qty', label: 'Miktar', type: 'number', step: '0.1' }, { name: 'price', label: 'Satış fiyatı (₺)', type: 'number', step: '0.01' }], values: { qty: 1 } }); if (!v) return; const x = db.get('materials', v.m); return addLine({ type: /menteşe|ray|kulp/i.test(x.name) ? 'aksesuar' : 'malzeme', mid: x.id, name: x.name, qty: Number(v.qty) || 1, unit: x.unit, price: Number(v.price) || x.cost, cost: x.cost }); }
      if (b.hasAttribute('data-msign')) { const s = await NS.sign({ title: 'Ölçü onayı — müşteri imzası', label: 'Müşteri adı soyadı', name: cus(j.customer).name, text: esc(measureLines(j) || 'Ölçü kaydı yok') + '<br><br>Yukarıdaki ölçüleri yerinde kontrol ettim, doğru olduğunu onaylıyorum.' }); if (s) { j.measureSign = s; db.save(); draw(); } return; }
      if (b.dataset.pr) { const d = { teklif: () => quoteDoc(j, 'teklif'), sozlesme: () => quoteDoc(j, 'sozlesme'), foy: () => workDoc(j), teslim: () => deliveryDoc(j), garanti: () => warrantyDoc(j) }[b.dataset.pr](); NS.docs.print(b.dataset.pr, d); return; }
      if (b.hasAttribute('data-link')) { try { await navigator.clipboard.writeText(linkOf(j)); toast('Müşteri linki kopyalandı', 'ok'); } catch (x) { NS.prompt('Müşteri linki', linkOf(j)); } return; }
      if (b.dataset.pay) { await takePayment(j, b.dataset.pay, draw); return; }
      if (b.dataset.act === 'rc') { const p = db.get('payments', b.dataset.id); if (p) NS.docs.print('makbuz', receiptDoc(p)); return; }
      if (b.hasAttribute('data-claim')) { if (await newClaim(j)) app.go('servis'); return; }
      if (b.hasAttribute('data-addp')) { const t = await NS.prompt('Eksik veya servis işi', ''); if (t) { (j.punch = j.punch || []).push({ id: NS.uid(), text: t, done: false, created: new Date().toISOString() }); db.save(); draw(); } return; }
      if (b.dataset.flow) await flow(b.dataset.flow);
    });
    async function flow(k) {
      let msg = null;
      if (k === 'olcu') { const v = await formModal({ title: 'Ölçü randevusu', fields: [{ name: 'measureAt', label: 'Tarih', type: 'date', required: true }, { name: 'measurer', label: 'Ölçüyü alacak kişi' }], values: { measureAt: j.measureAt || iso(addDays(new Date(), 1)), measurer: (NS.currentUser || {}).name } }); if (!v) return; Object.assign(j, v); setSt(j, 'olcu', `Ölçü randevusu ${NS.date(v.measureAt)}`); tab = 'olcu'; msg = [`${S().bizName}: ${NS.date(v.measureAt)} tarihinde ölçü için geleceğiz. Bilgi: ${S().bizPhone || ''}`, 'Ölçü randevusu']; }
      else if (k === 'teklif') { if (!(j.measures || []).length && !(await confirm('Ölçü girilmedi. Yine de teklife geçilsin mi?', { danger: false }))) return; j.measureRev = (j.measureRev || 0) + 1; setSt(j, 'teklif', `${(j.measures || []).length} ölçü kaydedildi`); tab = 'teklif'; }
      else if (k === 'gonder') { if (!(j.items || []).length) return toast('Önce teklif kalemlerini ekleyin', 'err'); j.quoteSent = new Date().toISOString(); (j.history = j.history || []).push({ at: j.quoteSent, st: 'teklif', note: `Sürüm ${j.quoteV || 1} müşteriye açıldı`, user: (NS.currentUser || {}).name }); msg = [`${S().bizName}: ${j.title} için ${money(T(j).total)} tutarında teklifiniz hazır. İnceleyip onaylayın: ${linkOf(j)}`, 'Teklif']; }
      else if (k === 'onay') { if (!(j.items || []).length) return toast('Önce teklif kalemlerini ekleyin', 'err'); const s = await NS.sign({ title: 'Teklif onayı — müşteri imzası', label: 'Müşteri adı soyadı', name: cus(j.customer).name, text: `<b>${esc(j.title)}</b> için <b>${money(T(j).total)}</b> tutarındaki teklifi ve ölçüleri onaylıyorum.` }); if (!s && !(await confirm('İmza alınmadan onaylandı sayılsın mı? (telefonla onay)', { danger: false }))) return; j.approval = s ? { ...s, via: 'yüz yüze' } : { name: cus(j.customer).name, at: new Date().toISOString(), via: 'telefon' }; (j.quotes = j.quotes || []).push(O.snapshot(j, vat())); setSt(j, 'onay', `Teklif onaylandı (${j.approval.via})`); tab = 'odeme'; }
      else if (k === 'kapora') { if (paid(j) <= 0.01) { const p = await takePayment(j, 'kapora'); if (!p) return; } if (!O.depositOk(j, pays(), S().minDeposit, vat()) && !(await confirm(`Alınan ödeme asgari kaporanın (%${S().minDeposit || 0}) altında. Yine de üretime gönderilsin mi?`, { danger: false }))) return; const short = useMaterials(j); setSt(j, 'uretim', `${j.revised ? 'Değişiklikle üretime döndü' : 'Üretime alındı'} · alınan ${money(paid(j))}`); tab = 'uretim'; if (short.length) toast('Stok yetersiz: ' + short.join(', '), 'err'); msg = [`${S().bizName}: Ödemeniz alındı, ${j.title} üretime girdi. Durum: ${linkOf(j)}`, 'Üretim bilgisi']; }
      else if (k === 'revize') { if (!(await confirm('Teklif yeni sürümle açılır ve müşteri yeniden onaylar. Kaporalar korunur. Devam edilsin mi?', { danger: false }))) return; j.quoteV = (j.quoteV || 1) + 1; j.measureRev = (j.measureRev || 1) + 1; j.measureSign = null; if (j.status === 'uretim') j.revised = true; j.approval = null; j.contractSign = null; setSt(j, 'teklif', `Değişiklik teklifi: sürüm ${j.quoteV}`); tab = 'teklif'; }
      else if (k === 'montaj') { const v = await formModal({ title: 'Montaj planı', fields: [{ name: 'installAt', label: 'Montaj tarihi', type: 'date', required: true }, { name: 'team', label: 'Ekip', type: 'select', required: true, options: db.all('teams').map((t) => ({ value: t.id, label: t.name })) }], values: { installAt: j.installAt || iso(addDays(new Date(), 2)), team: j.team } }); if (!v) return; const clash = db.all('jobs', (x) => x.id !== j.id && x.status === 'montaj' && x.team === v.team && x.installAt === v.installAt); if (clash.length && !(await confirm(`${team(v.team).name} o gün ${clash[0].no} işinde. Yine de planlansın mı?`, { danger: false }))) return; Object.assign(j, v); setSt(j, 'montaj', `Montaj ${NS.date(v.installAt)} · ${team(v.team).name}`); tab = 'teslim'; msg = [`${S().bizName}: ${j.title} montajınız ${NS.date(v.installAt)} tarihine planlandı.`, 'Montaj tarihi']; }
      else if (k === 'teslim') { if (!(await deliver())) return; }
      else if (k === 'iptal') { const v = await formModal({ title: 'İşi iptal et', fields: [{ name: 'cancel', label: 'İptal nedeni', required: true, full: true }, ...(paid(j) > 0 ? [{ name: 'refund', label: `Müşteriye iade (alınan ${money(paid(j))})`, type: 'number', step: '0.01' }] : [])], values: { refund: 0 } }); if (!v) return; j.cancel = v.cancel; if (Number(v.refund) > 0) db.insert('payments', { job: j.id, customer: j.customer, amount: Number(v.refund), kind: 'iade', method: 'İade', at: new Date().toISOString() }, true); setSt(j, 'iptal', v.cancel); }
      db.save(); draw(); if (msg) tell(j, msg[0], msg[1]);
    }
    async function deliver() {
      const P = O.openPunch(j); const t = T(j); const rest = Math.max(0, left(j));
      const v = await formModal({ title: `Teslim — ${j.no}`, fields: [{ name: 'amount', label: `Şimdi tahsil edilen (kalan ${money(rest)})`, type: 'number', step: '0.01' }, { name: 'method', label: 'Yöntem', type: 'select', options: ['Havale', 'Nakit', 'Kredi kartı', 'Borç kalsın'] }, { name: 'efatura', label: 'e-Arşiv / e-Fatura kes', type: 'checkbox' }, { name: 'print', label: 'Teslim tutanağını yazdır', type: 'checkbox' }], values: { amount: rest, method: 'Havale', print: true }, extra: P.length ? `<div class="small" style="color:var(--warn)">${P.length} açık eksik var; tutanağa yazılır ve Özet ekranında kalır.</div>` : '' });
      if (!v) return false; const sig = await NS.sign({ title: 'Teslim — müşteri imzası', label: 'Teslim alan adı soyadı', name: cus(j.customer).name, text: `<b>${esc(j.title)}</b> işini kontrol ederek teslim aldım.${P.length ? ' Açık eksikler tutanakta yazılıdır.' : ''}` });
      if (!sig && !(await confirm('Müşteri imzası alınmadan teslim edilsin mi?'))) return false;
      const got = v.method === 'Borç kalsın' ? 0 : Number(v.amount) || 0; if (got > 0) db.insert('payments', { job: j.id, customer: j.customer, amount: got, kind: 'son', method: v.method, at: new Date().toISOString(), user: (NS.currentUser || {}).name }, true);
      j.signOut = sig || null; j.deliveredAt = new Date().toISOString(); j.warrantyUntil = iso(addDays(new Date(), Number(S().warrantyDays) || 0));
      if (v.efatura && NS.ebelge) { const c = cus(j.customer); const r = await NS.ebelge.create({ docType: 'auto', buyer: c.name, buyerVkn: c.taxNo, address: c.address, no: j.no, lines: (j.items || []).map((i) => ({ name: i.name, qty: i.qty, unit: i.unit || 'adet', price: i.price, vat: t.rate })), note: j.title }); if (r && r.no) j.invoice = r.no + (r.simulated ? ' (TEST)' : ''); else if (r && r.error) toast('Fatura kesilemedi: ' + r.error, 'err'); }
      setSt(j, 'teslim', `${sig ? 'Müşteri imzaladı' : 'İmzasız'}${j.invoice ? ' · fatura ' + j.invoice : ''}`); db.save(); if (v.print) NS.docs.print('teslim', deliveryDoc(j)); return true;
    }
    draw();
  }

  // ---------- Atölye panosu: işler bulundukları aşamada görünür ----------
  function prodPage(el, p, app) {
    const L = () => db.all('jobs', (j) => j.status === 'uretim').sort((a, b) => String(a.deadline).localeCompare(String(b.deadline)));
    el.innerHTML = pageHead('Atölye panosu', 'Üretimdeki işler bulundukları aşamada görünür; termini yakın olan üsttedir') + `<div class="grid" style="grid-template-columns:repeat(${O.STAGES.length},minmax(170px,1fr));overflow-x:auto;gap:12px" id="kb"></div>`;
    const draw = () => { const all = L(); $('#kb', el).innerHTML = O.STAGES.map(([k, l]) => { const R = all.filter((j) => O.curStage(j) === k); return `<div><div class="row mb"><b class="grow">${esc(l)}</b>${badge(R.length, 'acc')}</div>${R.map((j) => `<div class="card pad mb"><a href="#/is/${j.id}" style="color:inherit"><b>${esc(j.title)}</b> ${j.revised ? badge('Ölçü sürüm ' + (j.measureRev || 1), 'warn') : ''}<div class="small muted">${esc(cus(j.customer).name)} · ${esc(j.no)}</div></a><div class="row small mt"><span class="grow ${O.late(j, today()) ? '' : 'faint'}" ${O.late(j, today()) ? 'style="color:var(--err)"' : ''}>Termin ${j.deadline ? NS.date(j.deadline) : '-'}</span><button class="btn sm primary" data-next="${j.id}" data-k="${k}">${icon('check')} Bitti</button></div></div>`).join('') || '<div class="small faint">—</div>'}</div>`; }).join('') ; if (!all.length) $('#kb', el).insertAdjacentHTML('beforebegin', ''); };
    on(el, 'click', '[data-next]', (e, b) => { const j = db.get('jobs', b.dataset.next); j.revised = false; j.stages = j.stages || {}; j.stages[b.dataset.k] = { at: new Date().toISOString(), by: (NS.currentUser || {}).name || '' }; (j.history = j.history || []).push({ at: new Date().toISOString(), st: 'uretim', note: `${(O.STAGES.find((s) => s[0] === b.dataset.k) || [0, ''])[1]} bitti`, user: (NS.currentUser || {}).name }); db.save(); draw(); if (O.stageDone(j) === O.STAGES.length) toast(`${j.no} üretimi bitti, montaja planlanabilir`, 'ok'); });
    draw();
  }

  // ---------- Montaj takvimi: 14 gün + bekleyenler + açık eksikler ----------
  function installPage(el, p, app) {
    const mine = myTeam(); const J = () => db.all('jobs', (j) => !mine || j.team === mine);
    const draw = () => {
      const days = Array.from({ length: 14 }, (_, i) => iso(addDays(new Date(), i))); const A = J().filter((j) => j.status === 'montaj');
      const late = A.filter((j) => j.installAt && j.installAt < today());
      const ready = mine ? [] : J().filter((j) => j.status === 'uretim' && O.stageDone(j) === O.STAGES.length);
      const punch = J().filter((j) => j.status !== 'iptal' && O.openPunch(j).length);
      const rowJ = (j) => `<a class="list-item" href="#/is/${j.id}" style="color:inherit"><span class="grow"><b>${esc(j.title)}</b><div class="small muted">${esc(cus(j.customer).name)} · ${esc(j.address || '')}</div></span><span class="small faint">${esc(team(j.team).name)}</span></a>`;
      el.innerHTML = pageHead('Montaj takvimi', 'Önümüzdeki 14 gün, geciken montajlar ve açık eksikler') + `<div class="grid g-21"><div class="col" style="gap:12px">${late.length ? `<div class="card" style="border-color:var(--err)"><div class="card-h"><h3>Geciken montaj (${late.length})</h3></div>${late.map(rowJ).join('')}</div>` : ''}${days.map((d) => { const L = A.filter((j) => j.installAt === d); return L.length ? `<div class="card"><div class="card-h"><h3>${esc(NS.dateLong(new Date(d + 'T12:00:00')))}</h3>${badge(L.length, 'info')}</div>${L.map(rowJ).join('')}</div>` : ''; }).join('') || '<div class="card"><div class="empty"><div>Önümüzdeki 14 günde montaj yok</div></div></div>'}</div>
        <div class="col" style="gap:12px">${mine ? '' : `<div class="card"><div class="card-h"><h3>Montaja hazır (${ready.length})</h3></div>${ready.map((j) => `<a class="list-item" href="#/is/${j.id}" style="color:inherit"><span class="grow"><b>${esc(j.title)}</b><div class="small muted">${esc(cus(j.customer).name)}</div></span></a>`).join('') || '<div class="empty"><div>Bekleyen yok</div></div>'}</div>`}<div class="card"><div class="card-h"><h3>Açık eksikler (${punch.length})</h3></div>${punch.map((j) => `<a class="list-item" href="#/is/${j.id}" style="color:inherit"><span class="grow"><b>${esc(cus(j.customer).name)}</b><div class="small muted">${esc(O.openPunch(j).map((x) => x.text).join(', '))}</div></span>${O.closed(j) ? badge('Teslim sonrası', 'warn') : ''}</a>`).join('') || '<div class="empty"><div>Açık eksik yok</div></div>'}</div></div></div>`;
    };
    draw();
  }

  // ---------- Ayıp ve servis kayıtları: 6 ay, 30 iş günü ve 2 yıl sayaçları (6502 m.10, 11, 12) ----------
  async function newClaim(j) {
    const v = await formModal({ title: `Ayıp ve servis kaydı — ${j.no}`, fields: [{ name: 'text', label: 'Müşterinin bildirdiği sorun', type: 'textarea', required: true, full: true }, { name: 'at', label: 'Bildirim tarihi', type: 'date', required: true }, { name: 'choice', label: 'Müşterinin seçtiği hak', type: 'select', options: Object.entries(O.CLAIM).map(([value, label]) => ({ value, label })) }], values: { at: today(), choice: 'onarim' } });
    if (!v) return null; const c = db.insert('claims', { job: j.id, customer: j.customer, text: v.text, at: v.at, choice: v.choice, status: 'acik', due: O.workdays(v.at, 30) }, true); db.log('Ayıp kaydı açıldı', j.no); db.save(); toast('Kayıt açıldı', 'ok'); return c;
  }
  function claimsPage(el, p, app) {
    const draw = () => {
      const L = db.all('claims').sort((a, b) => String(b.at).localeCompare(String(a.at))); const open = L.filter((c) => c.status === 'acik');
      el.innerHTML = pageHead('Ayıp ve servis', 'Teslim sonrası bildirimler. Onarım ve değişim süresi burada izlenir.') + `<div class="grid g3 mb">${kpi('Açık kayıt', open.length, 'alert', open.length ? 'warn' : 'ok')}${kpi('Süresi geçen', open.filter((c) => c.due < today()).length, 'clock', open.some((c) => c.due < today()) ? 'err' : 'ok')}${kpi('Toplam', L.length, 'list', 'info')}</div><div class="card">${table({ rows: L, empty: 'Henüz kayıt yok. Teslim edilen işin kartından açılır.', emptyIcon: 'check', columns: [{ label: 'İş', render: (c) => { const j = db.get('jobs', c.job) || {}; return `<a href="#/is/${esc(c.job)}"><b>${esc(j.title || '-')}</b></a><div class="small faint">${esc(cus(c.customer).name)} · ${esc(j.no || '')}</div>`; } }, { label: 'Sorun', render: (c) => `<span class="small">${esc(c.text)}</span><div class="small faint">${esc(O.CLAIM[c.choice] || '')}</div>` }, { label: 'Bildirim', render: (c) => NS.date(c.at) }, { label: 'Son gün', render: (c) => (c.status === 'acik' ? (c.due < today() ? badge(NS.date(c.due), 'err') : NS.date(c.due)) : '-') }, { label: 'Süreler', render: (c) => { const f = O.claimFlags(db.get('jobs', c.job) || {}, c.at); return `${f.m6 ? badge('İlk 6 ay', 'warn') : ''} ${f.y2 ? badge('2 yıl içinde', 'info') : badge('2 yıl geçti', '')}`; } }, { label: 'Durum', render: (c) => (c.status === 'acik' ? badge('Açık', 'warn') : badge('Çözüldü ' + NS.date(c.doneAt), 'ok')) }], actions: [{ icon: 'check', act: 'ok', title: 'Çözüldü', show: (c) => c.status === 'acik' }] })}</div><p class="small muted mt">Son gün hafta sonu hariç 30 iş günüdür, resmî tatiller düşülmez. Hak ve süre yorumu için hukuk danışmanınıza başvurun.</p>`;
    };
    on(el, 'click', '[data-act=ok]', async (e, b) => { const c = db.get('claims', b.dataset.id); const n = await NS.prompt('Yapılan çözüm', ''); if (n === null) return; c.status = 'cozuldu'; c.solution = n; c.doneAt = new Date().toISOString(); db.save(); draw(); toast('Kayıt kapatıldı', 'ok'); });
    draw();
  }

  // ---------- Müşteriler ve ekstre ----------
  const custJobs = (c) => (jobsBy().get(c.id) || []).filter((j) => j.status !== 'iptal');
  const custBal = (c) => O.r2(sum(custJobs(c).filter((j) => O.locked(j)), (j) => left(j)));
  function customersPage(el, p, app) {
    NS.crud(el, app, { col: 'customers', title: 'Müşteriler', sub: 'Eski işler, açık bakiye ve iletişim', single: 'Müşteri', addLabel: 'Müşteri ekle', emptyIcon: 'users',
      fields: [{ name: 'name', label: 'Ad / firma', required: true }, { name: 'phone', label: 'Telefon', type: 'tel', required: true }, { name: 'address', label: 'Adres', full: true }, { name: 'taxNo', label: 'VKN / TCKN' }, { name: 'source', label: 'Nereden geldi' }],
      filters: [{ value: 'all', label: 'Tümü' }, { value: 'borc', label: 'Borcu olan', test: (c) => custBal(c) > 0.01 }],
      searchFields: (c) => [c.name, c.phone, c.address],
      columns: [{ key: 'name', label: 'Müşteri', render: (c) => `<b>${esc(c.name)}</b><div class="small faint">${esc(c.phone)}</div>` }, { label: 'İş', cls: 'right', render: (c) => custJobs(c).length }, { label: 'Bakiye', cls: 'right', render: (c) => { const b = custBal(c); return b > 0.01 ? `<b style="color:var(--err)">${money(b)}</b>` : '<span class="faint">0</span>'; } }],
      canDelete: (c) => (custJobs(c).length ? 'Bu müşterinin işleri var, silinemez' : true),
      extraActions: [{ icon: 'plus', act: 'job', title: 'Yeni talep' }, { icon: 'list', act: 'ext', title: 'Hesap ekstresi' }], onAction: (a, c) => (a === 'job' ? newJob(app, { customer: c.id, address: c.address }) : statement(c)) });
  }
  function statement(c) {
    const mv = [...custJobs(c).filter((j) => O.locked(j)).map((j) => ({ at: (j.approval && j.approval.at) || j.at, doc: j.no, text: j.title, b: T(j).total, a: 0 })), ...pays().filter((x) => x.customer === c.id).map((x) => ({ at: x.at, doc: (db.get('jobs', x.job) || {}).no || '', text: `${O.PAY[x.kind] || 'Ödeme'} · ${x.method || ''}`, b: x.kind === 'iade' ? x.amount : 0, a: x.kind === 'iade' ? 0 : x.amount }))].sort((x, y) => x.at.localeCompare(y.at));
    let bal = 0; mv.forEach((m) => { bal = O.r2(bal + m.b - m.a); m.bal = bal; });
    modal({ title: `Hesap ekstresi — ${c.name}`, size: 'lg', body: `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Tarih</th><th>İş</th><th>Açıklama</th><th class="right">Borç</th><th class="right">Alacak</th><th class="right">Bakiye</th></tr></thead><tbody>${mv.map((m) => `<tr><td class="small">${NS.date(m.at)}</td><td class="mono small">${esc(m.doc)}</td><td class="small">${esc(m.text)}</td><td class="right">${m.b ? money(m.b) : ''}</td><td class="right">${m.a ? money(m.a) : ''}</td><td class="right"><b>${money(m.bal)}</b></td></tr>`).join('') || '<tr><td colspan="6" class="center muted">Hareket yok</td></tr>'}</tbody></table></div>`,
      actions: [{ label: 'CSV indir', icon: 'download', onClick: () => NS.csv('ekstre-' + c.name, mv.map((m) => ({ Tarih: NS.date(m.at), İş: m.doc, Açıklama: m.text, Borç: m.b, Alacak: m.a, Bakiye: m.bal }))) }, { label: 'WhatsApp ile gönder', icon: 'message', cls: 'primary', onClick: () => window.open(waLink(c.phone, `${S().bizName} — hesap özetiniz: güncel bakiye ${money(bal)}.`), '_blank', 'noopener') }] });
  }

  // ---------- Malzeme stoğu ve satınalma listesi ----------
  function materialsPage(el, p, app) {
    const showCost = () => role() === 'admin' || role() === 'ofis' || !role();
    NS.crud(el, app, { col: 'materials', title: 'Malzeme stoğu', sub: 'Üretime alınan işin malzemesi stoktan düşer', single: 'Malzeme', addLabel: 'Malzeme ekle', emptyIcon: 'box',
      fields: [{ name: 'code', label: 'Kod', required: true }, { name: 'name', label: 'Malzeme adı', required: true, full: true }, { name: 'unit', label: 'Birim', type: 'select', options: ['plaka', 'm', 'm²', 'adet', 'takım', 'kutu', 'kg', 'lt'] }, { name: 'cost', label: 'Alış (₺)', type: 'number', step: '0.01' }, { name: 'stock', label: 'Stok', type: 'number', step: '0.1' }, { name: 'min', label: 'En az stok', type: 'number', step: '0.1' }, { name: 'supplier', label: 'Tedarikçi' }],
      filters: [{ value: 'all', label: 'Tümü' }, { value: 'krit', label: 'Kritik', test: (x) => (x.stock || 0) <= (x.min || 0) }], searchFields: (x) => [x.code, x.name, x.supplier],
      columns: [{ key: 'code', label: 'Kod', render: (x) => `<span class="mono">${esc(x.code)}</span>` }, { key: 'name', label: 'Malzeme', render: (x) => `<b>${esc(x.name)}</b><div class="small faint">${esc(x.supplier || '')}</div>` }, { key: 'stock', label: 'Stok', cls: 'right', render: (x) => `<b style="color:var(--${(x.stock || 0) <= (x.min || 0) ? 'err' : 'text'})">${NS.num(x.stock || 0)}</b> <span class="small faint">${esc(x.unit || '')}</span>` }, ...(showCost() ? [{ key: 'cost', label: 'Alış', cls: 'right', render: (x) => money(x.cost) }] : [])],
      extraActions: [{ icon: 'plus', act: 'in', title: 'Stok girişi' }],
      onAction: async (a, x, draw) => { const v = await formModal({ title: `Stok girişi — ${x.name}`, fields: [{ name: 'qty', label: `Gelen miktar (${x.unit || ''})`, type: 'number', step: '0.1', required: true }, { name: 'cost', label: 'Yeni alış fiyatı (₺)', type: 'number', step: '0.01' }], values: { cost: x.cost } }); if (!v) return; x.stock = O.r2((x.stock || 0) + Number(v.qty)); if (v.cost !== '' && v.cost != null) x.cost = Number(v.cost); db.save(); draw(); toast('Stok güncellendi', 'ok'); } });
    const h = $('.page-h .row', el); if (h) h.insertAdjacentHTML('afterbegin', `<button class="btn" data-order>${icon('truck')} Eksik malzeme listesi</button>`);
    on(el, 'click', '[data-order]', () => {
      const need = {}; db.all('jobs', (j) => ['onay', 'teklif'].includes(j.status)).forEach((j) => Object.entries(O.usage(j)).forEach(([id, q]) => { need[id] = (need[id] || 0) + q; }));
      const rows = db.all('materials').map((m) => ({ m, q: O.r2(Math.max(0, (need[m.id] || 0) + (m.min || 0) - (m.stock || 0))) })).filter((r) => r.q > 0);
      if (!rows.length) return toast('Eksik malzeme yok'); const text = `${S().bizName} — malzeme siparişi (${NS.date(new Date())})\n` + rows.map((r) => `• ${r.m.code} · ${r.m.name} — ${r.q} ${r.m.unit || ''}`).join('\n');
      modal({ title: 'Eksik malzeme listesi', size: 'lg', body: `<p class="small muted mb">Stok, en az stok ve onay bekleyen işlerin ihtiyacına göre hesaplanır. Sipariş otomatik iletilmez.</p><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Kod</th><th>Malzeme</th><th class="right">Stok</th><th class="right">Alınacak</th></tr></thead><tbody>${rows.map((r) => `<tr><td class="mono">${esc(r.m.code)}</td><td>${esc(r.m.name)}</td><td class="right">${NS.num(r.m.stock || 0)}</td><td class="right"><b>${r.q} ${esc(r.m.unit || '')}</b></td></tr>`).join('')}</tbody></table></div>`, actions: [{ label: 'CSV indir', icon: 'download', onClick: () => NS.csv('eksik-malzeme', rows.map((r) => ({ Kod: r.m.code, Malzeme: r.m.name, Stok: r.m.stock, Alınacak: r.q, Birim: r.m.unit }))) }, { label: 'Kopyala', icon: 'copy', cls: 'primary', onClick: async () => { try { await navigator.clipboard.writeText(text); toast('Liste kopyalandı', 'ok'); } catch (e) { NS.prompt('Liste', text); } } }] });
    });
  }
  function catalogPage(el, p, app) {
    NS.crud(el, app, { col: 'catalog', title: 'Fiyat kataloğu', sub: 'Teklife tek tıkla eklenen işçilik ve hizmetler', single: 'Kalem', addLabel: 'Kalem ekle', emptyIcon: 'book',
      fields: [{ name: 'name', label: 'Ad', required: true, full: true }, { name: 'type', label: 'Tür', type: 'select', options: Object.entries(O.KT).map(([value, [label]]) => ({ value, label })) }, { name: 'unit', label: 'Birim' }, { name: 'price', label: 'Satış (₺)', type: 'number', step: '0.01', required: true }, { name: 'cost', label: 'Maliyet (₺)', type: 'number', step: '0.01' }],
      searchFields: (x) => [x.name], columns: [{ key: 'name', label: 'Kalem', render: (x) => `<b>${esc(x.name)}</b>` }, { label: 'Tür', render: (x) => badge((O.KT[x.type] || [''])[0], (O.KT[x.type] || ['', ''])[1]) }, { key: 'unit', label: 'Birim' }, { key: 'price', label: 'Satış', cls: 'right', render: (x) => money(x.price) }, { key: 'cost', label: 'Maliyet', cls: 'right', render: (x) => money(x.cost || 0) }] });
  }
  function teamsPage(el, p, app) {
    NS.crud(el, app, { col: 'teams', title: 'Montaj ekipleri', sub: 'Takvimdeki ekipler', single: 'Ekip', addLabel: 'Ekip ekle', emptyIcon: 'users', fields: [{ name: 'name', label: 'Ekip adı', required: true }, { name: 'lead', label: 'Sorumlu' }, { name: 'phone', label: 'Telefon', type: 'tel' }], searchFields: (x) => [x.name, x.lead], columns: [{ key: 'name', label: 'Ekip', render: (x) => `<b>${esc(x.name)}</b>` }, { key: 'lead', label: 'Sorumlu', render: (x) => esc(x.lead || '') }, { key: 'phone', label: 'Telefon', render: (x) => esc(x.phone || '') }, { label: 'Açık montaj', cls: 'right', render: (x) => db.all('jobs', (j) => j.team === x.id && j.status === 'montaj').length }], canDelete: (x) => (db.all('jobs', (j) => j.team === x.id && !O.closed(j)).length ? 'Bu ekibin açık işi var' : true) });
  }

  // ---------- Raporlar: kârlılık ve kaynak ----------
  function reportPage(el, p, app) {
    const D = db.all('jobs', (j) => j.status === 'teslim').sort((a, b) => (b.deliveredAt || '').localeCompare(a.deliveredAt || ''));
    const rows = D.map((j) => { const t = T(j); const c = O.costOf(j); return { id: j.id, j, net: t.net, c, k: O.r2(t.net - c), pct: t.net ? Math.round(((t.net - c) / t.net) * 100) : 0 }; });
    const bySrc = Object.entries(NS.groupBy(db.all('jobs'), (j) => j.source || 'Belirsiz')).map(([s, L]) => ({ id: s, s, n: L.length, won: L.filter((j) => O.locked(j) && j.status !== 'iptal').length })).sort((a, b) => b.n - a.n);
    el.innerHTML = pageHead('Raporlar', 'Teslim edilen işlerin kârlılığı ve talep kaynakları', `<button class="btn" id="cs">${icon('download')} Excel (CSV)</button>`) + `<div class="grid g3 mb">${kpi('Teslim edilen', D.length, 'check', 'ok')}${kpi('KDV hariç ciro', money(sum(rows, (r) => r.net)), 'trend', 'info')}${kpi('Brüt kâr', money(sum(rows, (r) => r.k)), 'wallet', 'ok', '<div class="small faint">kalem maliyetlerine göre</div>')}</div><div class="grid g-21"><div class="card"><div class="card-h"><h3>İş kârlılığı</h3></div>${table({ rows: rows.slice(0, 100), empty: 'Henüz teslim edilen iş yok', emptyIcon: 'chart', columns: [{ label: 'İş', render: (r) => `<a href="#/is/${r.id}"><b>${esc(r.j.title)}</b></a> <span class="small faint">${esc(r.j.no)}</span><div class="small faint">${esc(cus(r.j.customer).name)}</div>` }, { label: 'Ciro', cls: 'right', render: (r) => money(r.net) }, { label: 'Maliyet', cls: 'right', render: (r) => money(r.c) }, { label: 'Kâr', cls: 'right', render: (r) => `<b style="color:var(--${r.k < 0 ? 'err' : 'text'})">${money(r.k)}</b> <span class="small faint">%${r.pct}</span>` }] })}</div><div class="card"><div class="card-h"><h3>Talep kaynağı</h3></div>${table({ rows: bySrc, empty: 'Veri yok', columns: [{ label: 'Kaynak', render: (r) => esc(r.s) }, { label: 'Talep', cls: 'right', render: (r) => r.n }, { label: 'Onaylanan', cls: 'right', render: (r) => `${r.won} <span class="small faint">%${r.n ? Math.round((r.won / r.n) * 100) : 0}</span>` }] })}</div></div>`;
    $('#cs', el).onclick = () => NS.csv('is-karliligi', rows.map((r) => ({ İş: r.j.no, Ad: r.j.title, Müşteri: cus(r.j.customer).name, Ciro: r.net, Maliyet: r.c, Kâr: r.k })));
  }

  // ---------- Özet ----------
  function dashboard(el, p, app) {
    const all = db.all('jobs'); const open = all.filter((j) => !O.closed(j)); const late = open.filter((j) => O.late(j, today()));
    const soon = iso(addDays(new Date(), 7)); const week = open.filter((j) => j.status === 'montaj' && j.installAt && j.installAt <= soon);
    const due = O.r2(sum(all.filter((j) => O.locked(j) && j.status !== 'iptal'), (j) => Math.max(0, left(j)))); const crit = db.all('materials', (x) => (x.stock || 0) <= (x.min || 0));
    const m30 = all.filter((j) => j.status === 'teslim' && (j.deliveredAt || '') > addDays(new Date(), -30).toISOString());
    const ser = NS.dailySeries(pays().filter((x) => x.kind !== 'iade'), 14, 'at', (x) => x.amount); const punch = all.filter((j) => j.status !== 'iptal' && O.openPunch(j).length);
    el.innerHTML = pageHead(S().bizName, NS.dateLong(new Date()), `<button class="btn primary" id="ad">${icon('plus')} Yeni talep</button>`) + `<div class="grid g4 mb">${kpi('Açık iş', open.length, 'kanban', 'info', `<div class="small faint">${open.filter((j) => j.status === 'uretim').length} üretimde</div>`)}${kpi('Termini geçen', late.length, 'alert', late.length ? 'err' : 'ok')}${kpi('7 günde montaj', week.length, 'calendar', 'warn', `<div class="small faint">${punch.length} işte açık eksik</div>`)}${kpi('Tahsil edilecek', money(due), 'wallet', 'err', `<div class="small faint">30 günde ${m30.length} teslim</div>`)}</div>
      <div class="grid g-21 mb"><div class="card"><div class="card-h"><h3>Son 14 gün tahsilat</h3></div><div class="card-b">${chart.bars(ser.labels.map((l, i) => ({ label: l, value: ser.values[i] })))}</div></div><div class="card"><div class="card-h"><h3>İş durumu</h3></div><div class="card-b">${open.length ? chart.donut(O.FLOW.slice(0, 6).map((s) => ({ label: O.ST[s][0], value: open.filter((j) => j.status === s).length })).filter((x) => x.value), { size: 130 }) : '<div class="empty"><div>Açık iş yok</div></div>'}</div></div></div>
      <div class="grid g2"><div class="card"><div class="card-h"><h3>Termini geçen işler</h3></div>${table({ rows: late.slice(0, 8), empty: 'Geciken iş yok', emptyIcon: 'check', columns: [{ label: 'İş', render: (j) => `<a href="#/is/${j.id}"><b>${esc(j.title)}</b></a><div class="small faint">${esc(cus(j.customer).name)}</div>` }, { label: 'Durum', render: (j) => stB(j.status) }, { label: 'Termin', render: (j) => NS.date(j.deadline) }], actions: [{ icon: 'send', act: 'lt', title: 'Müşteriye gecikme haberi ver' }] })}</div><div class="card"><div class="card-h"><h3>Kritik malzeme</h3><a class="btn sm" href="#/malzeme">Stok</a></div>${table({ rows: crit.slice(0, 8), empty: 'Kritik malzeme yok', emptyIcon: 'check', columns: [{ label: 'Malzeme', render: (x) => `<b>${esc(x.name)}</b>` }, { label: 'Stok', cls: 'right', render: (x) => badge(`${NS.num(x.stock || 0)} ${x.unit || ''}`, 'err') }] })}</div></div>`;
    $('#ad', el).onclick = () => newJob(app);
    on(el, 'click', '[data-act=lt]', async (e, b) => { const j = db.get('jobs', b.dataset.id); const d = await NS.prompt('Yeni tahmini tarih (müşteriye gider)', ''); if (!d) return; (j.history = j.history || []).push({ at: new Date().toISOString(), st: j.status, note: 'Gecikme bildirimi hazırlandı: ' + d, user: (NS.currentUser || {}).name }); db.save(); tell(j, `${S().bizName}: ${j.title} işinizin termini gecikti, yeni tahmini tarih ${d}. Durum: ${linkOf(j)}`, 'Gecikme haberi'); });
  }

  const ROLES = { admin: 'Atölye sahibi', ofis: 'Satış ve ofis', usta: 'Atölye ustası', montaj: 'Montaj ekibi' };
  const app = NS.shell({
    id: 'mobilya', integrations: ['sms', 'whatsapp', 'efatura', 'printer', 'webhook', 'backup'], name: 'Mobilya & Özel İmalat', tagline: 'Ölçüden montaja atölye yönetimi', icon: 'factory', accent: '#a16207', db, home: 'ozet', auth: { roles: ROLES },
    nav: [{ sec: 'İşler' }, { id: 'ozet', label: 'Özet', icon: 'home', roles: ['ofis'] }, { id: 'isler', label: 'İşler', icon: 'kanban', roles: ['ofis', 'montaj'] }, { id: 'atolye', label: 'Atölye Panosu', icon: 'factory', roles: ['ofis', 'usta'] }, { id: 'montaj', label: 'Montaj Takvimi', icon: 'calendar', roles: ['ofis', 'montaj'] }, { sec: 'Yönetim' }, { id: 'servis', label: 'Ayıp ve Servis', icon: 'shield', roles: ['ofis'] }, { id: 'musteriler', label: 'Müşteriler', icon: 'users', roles: ['ofis'] }, { id: 'malzeme', label: 'Malzeme Stoğu', icon: 'box', roles: ['ofis'] }, { id: 'katalog', label: 'Fiyat Kataloğu', icon: 'book', roles: ['ofis'] }, { id: 'ekipler', label: 'Montaj Ekipleri', icon: 'users', roles: ['admin'] }, { id: 'rapor', label: 'Raporlar', icon: 'chart', roles: ['admin'] }, { id: 'ayarlar', label: 'Ayarlar', icon: 'settings', roles: ['admin'] }],
    titles: { is: 'İş kartı' },
    routes: { ozet: dashboard, isler: jobsPage, is: jobPage, atolye: prodPage, montaj: installPage, servis: claimsPage, musteriler: customersPage, malzeme: materialsPage, katalog: catalogPage, ekipler: teamsPage, rapor: reportPage,
      ayarlar: (el, p, a) => NS.settingsPage(el, a, { roles: ROLES, fields: [{ type: 'section', label: 'Teklif ve üretim' }, { name: 'vatRate', label: 'KDV oranı (%)', type: 'number' }, { name: 'minDeposit', label: 'Asgari kapora (%)', type: 'number' }, { name: 'deadlineDays', label: 'Varsayılan termin (gün)', type: 'number' }, { name: 'quoteDays', label: 'Teklif geçerlilik süresi (gün)', type: 'number' }, { name: 'warrantyDays', label: 'Garanti süresi (gün)', type: 'number' }, { name: 'warrantyText', label: 'Garanti belgesi metni (avukatınıza gösterin)', type: 'textarea', full: true }, { name: 'quoteNote', label: 'Teklif altı notu', type: 'textarea', full: true }, { name: 'contractText', label: 'Sözleşme metni (örnek metin yazmayın, avukatınıza gösterin)', type: 'textarea', full: true }] }) },
  });
  const R = role(); if ((R === 'usta' || R === 'montaj') && !location.hash) app.go(R === 'usta' ? 'atolye' : 'montaj');
})();
